inline_css:
.material-symbols-outlined {
  font-family: 'Material Symbols Outlined';
  font-weight: normal;
  font-style: normal;
  font-size: 20px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-feature-settings: 'liga';
  -webkit-font-smoothing: antialiased;
}

/* Orbital subtle custom scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: #0a1422;
}
::-webkit-scrollbar-thumb {
  background: #253653;
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: #7692ff;
}

.orbital-glow {
  box-shadow: 0 0 20px 2px rgba(118, 146, 255, 0.15);
}
.teal-glow {
  box-shadow: 0 0 16px 1px rgba(45, 212, 191, 0.15);
}
.amber-badge {
  background: rgba(251, 191, 36, 0.12);
  color: #FBBF24;
  border: 1px solid rgba(251, 191, 36, 0.25);
}
.critical-badge {
  background: rgba(251, 113, 133, 0.12);
  color: #FB7185;
  border: 1px solid rgba(251, 113, 133, 0.25);
}
